    "    function renderAgentLogMeta(snapshot){snapshot=snapshot||{};let meta=[];if(snapshot.path){meta.push(snapshot.path);}meta.push(formatLogSize(snapshot.size_bytes));if(snapshot.truncated){meta.push('Showing latest segment');}if(snapshot.error){meta.push(snapshot.error);}byId('agentLogMeta').textContent=meta.filter(Boolean).join(' · ');}\n"
    "    function renderAgentLog(snapshot){snapshot=snapshot||{};const previous=appState.agentLog||{};appState.agentLog=snapshot;const contentChanged=!agentLogBodyEquals(previous,snapshot);renderAgentLogMeta(snapshot);if(!contentChanged){return;}const textEl=byId('agentLogText');const previousScrollTop=textEl?textEl.scrollTop:0;const wasAtBottom=isAgentLogAtBottom(textEl);if(wasAtBottom){setAgentLogAutoScroll(true);}const text=snapshot.log||'';if(contentChanged){renderLogText(textEl,text,snapshot.exists?'Log is empty':'Log file is unavailable');}if(appState.agentLogAutoScroll){textEl.scrollTop=textEl.scrollHeight;}else if(textEl){textEl.scrollTop=previousScrollTop;}syncAgentLogAutoScroll();}\n"
    "    function applyPendingAgentLogSnapshotIfIdle(){const snapshot=appState.agentLogPendingSnapshot;if(!snapshot)return;const textEl=byId('agentLogText');if(agentLogSelectionActive(textEl))return;appState.agentLogPendingSnapshot=null;renderAgentLog(snapshot);}\n"
    "    async function refreshAgentLog(showBanner){const btn=byId('refreshAgentLogBtn');if(btn)btn.disabled=true;try{const payload=await request('/api/agent/logs',{method:'GET'});const snapshot=payload.agent_log||{};if(!showBanner&&agentLogSelectionActive(byId('agentLogText'))){renderAgentLogMeta(snapshot);if(!agentLogBodyEquals(appState.agentLog,snapshot)){appState.agentLogPendingSnapshot=snapshot;}else{appState.agentLog=snapshot;}return;}appState.agentLogPendingSnapshot=null;renderAgentLog(snapshot);if(showBanner){setBanner('Agent log refreshed.',false);}}catch(err){if(showBanner){renderLogText(byId('agentLogText'),'','Failed to load Agent log:\\n'+err.message);byId('agentLogMeta').textContent='';setBanner('Failed to refresh Agent log.',true);setDetails(err.message);}else{const snapshot=Object.assign({},appState.agentLog||{});snapshot.error=err.message;renderAgentLogMeta(snapshot);}}finally{if(btn)btn.disabled=false;updateAgentLogAutoScrollButton();}}\n"
    "    function toggleAgentLogAutoScroll(){const textEl=byId('agentLogText');setAgentLogAutoScroll(!appState.agentLogAutoScroll);if(appState.agentLogAutoScroll&&textEl){textEl.scrollTop=textEl.scrollHeight;refreshAgentLog(false);}}\n"
    "    function showOtaLogPanel(){const panel=byId('otaLogPanel');if(panel){panel.style.display='block';}appState.otaLogVisible=true;updateActionDetailsVisibility();}\n"
    "    function otaLogHasNewProgress(snapshot){snapshot=snapshot||{};if(!(snapshot.log||'')){return false;}if(!appState.otaLogPending){return true;}const size=Number(snapshot.size_bytes||0);const start=Number(appState.otaLogStartSize||0);return size>start||size<start;}\n"
    "    function extractOtaExitCode(text){const marker='[config_web] [ota] update_exited exit_code=';const idx=String(text||'').lastIndexOf(marker);if(idx<0){return null;}const match=String(text||'').slice(idx+marker.length).match(/^(\\d+)/);return match?Number(match[1]):null;}\n"
    "    function applyOtaExitCode(text){const rc=extractOtaExitCode(text);if(rc===null){return;}appState.otaLogPending=false;if(rc!==0){setBanner('OTA update failed (rc='+rc+').',true);setDetails('Recent OTA log:\\n'+String(text||'').slice(-4000),{keepOtaLog:true});}}\n"
    "    function setOtaLogPending(message,startSize){showOtaLogPanel();appState.otaLogPending=true;appState.otaLogStartSize=Number(startSize||0);renderLogText(byId('otaLogText'),message,'');byId('otaLogMeta').textContent='OTA update started, waiting for log output';}\n"
    "    function renderOtaLog(snapshot,options){snapshot=snapshot||{};options=options||{};appState.otaLog=snapshot;const textEl=byId('otaLogText');const stick=(textEl.scrollTop+textEl.clientHeight)>=(textEl.scrollHeight-16);const text=snapshot.log||'';if(options.preservePending&&appState.otaLogPending&&!otaLogHasNewProgress(snapshot)){let pendingMeta=[];if(snapshot.path){pendingMeta.push(snapshot.path);}pendingMeta.push('Waiting for OTA log output');pendingMeta.push(formatLogSize(snapshot.size_bytes));if(snapshot.error){pendingMeta.push(snapshot.error);}byId('otaLogMeta').textContent=pendingMeta.filter(Boolean).join(' · ');return;}if(text){appState.otaLogPending=false;renderLogText(textEl,text,'');applyOtaExitCode(text);}else{renderLogText(textEl,'',snapshot.exists?'Log is empty':'Log file is not readable yet');}let meta=[];if(snapshot.path){meta.push(snapshot.path);}meta.push(formatLogSize(snapshot.size_bytes));if(snapshot.truncated){meta.push('Showing latest segment');}if(snapshot.error){meta.push(snapshot.error);}byId('otaLogMeta').textContent=meta.filter(Boolean).join(' · ');if(stick){textEl.scrollTop=textEl.scrollHeight;}}\n"
    "    function selectOtaLogSnapshot(payload){payload=payload||{};const update=payload.ota_log||{};const health=payload.ota_health_log||{};if(appState.otaLogPending){return update;}if(update.log){return update;}if(health.log){return health;}return update.exists?update:health;}\n"
    "    async function refreshOtaLog(showBanner){if(!appState.otaLogVisible&&!showBanner){return;}if(showBanner){showOtaLogPanel();}const btn=byId('refreshOtaLogBtn');if(btn)btn.disabled=true;try{const payload=await request('/api/ota/logs',{method:'GET'});const snapshot=selectOtaLogSnapshot(payload);renderOtaLog(snapshot, {preservePending:true});const rc=extractOtaExitCode((payload.ota_log||{}).log||'');if(showBanner&&!(rc!==null&&rc!==0)){setBanner('OTA log refreshed.',false);}}catch(err){renderLogText(byId('otaLogText'),'','Failed to read OTA log:\\n'+err.message);byId('otaLogMeta').textContent='';if(showBanner){setBanner('Failed to refresh OTA log.',true);setDetails(err.message,{keepOtaLog:true});}}finally{if(btn)btn.disabled=false;}}\n"
    "    async function triggerOtaUpdate(){const btn=byId('otaUpdateBtn');setOtaLogPending('OTA update request sent, waiting for server confirmation...',appState.otaLogStartSize);if(btn)btn.disabled=true;setBanner('OTA update triggered.',false);setDetails('',{keepOtaLog:true});try{const payload=await request('/api/ota/update',{method:'POST'});setOtaLogPending('OTA update started, waiting for log output...',Number(payload.ota_log_start_size_bytes||0));setBanner('OTA update started.',false);setTimeout(function(){refreshOtaLog(false);},500);}catch(err){appState.otaLogPending=false;renderLogText(byId('otaLogText'),'','Failed to trigger OTA update:\\n'+err.message);byId('otaLogMeta').textContent='';setBanner('Failed to trigger OTA update.',true);setDetails(err.message,{keepOtaLog:true});}finally{if(btn)btn.disabled=false;}}\n"
    "    function otaHealthText(status){const names={success:'success',failed:'failed',pending:'pending confirmation',rolled_back:'rolled back'};return names[status]||status||'';}\n"
    "    function renderFirmwareInfo(fw){fw=fw||{};const versionEl=byId('fwVersion');if(fw.version){versionEl.textContent='Firmware version: '+fw.version;versionEl.style.display='';}else{versionEl.style.display='none';}const healthEl=byId('fwHealth');let parts=[];const status=fw.health_status||'';if(status){parts.push('OTA status: '+otaHealthText(status));}if(fw.phase){parts.push('phase: '+fw.phase);}if(fw.running_slot){parts.push('slot '+fw.running_slot);}if(fw.health_error){parts.push('error: '+fw.health_error);}if(fw.previous_version){parts.push('previous stable version: '+fw.previous_version);}healthEl.textContent=parts.join(' · ');healthEl.className='fw-health'+(status==='failed'?' error':'');healthEl.style.display=parts.length?'block':'none';if(status==='failed'){showOtaLogPanel();refreshOtaLog(false);}}\n"
    "    function savedWifiNetworks(){const wifi=appState.wifi||{};if(Array.isArray(wifi.networks))return wifi.networks;if(wifi.ssid)return [{ssid:wifi.ssid,psk:wifi.psk||'',priority:wifi.priority||1}];return [];}\n"
    "    function savedWifiBySsid(ssid){const nets=savedWifiNetworks();for(let i=0;i<nets.length;i++){if(nets[i].ssid===ssid)return nets[i];}return null;}\n"
    "    function connectedWifiSsid(){const status=appState.wifiStatus||{};return status.connected&&status.ssid?status.ssid:'';}\n"
    "    function addWifiName(names,seen,name){if(name&&!seen[name]){seen[name]=true;names.push(name);}}\n"
    "    function displayWifiNames(){const names=[];const seen={};savedWifiNetworks().slice().sort(function(a,b){return Number(b.priority||0)-Number(a.priority||0);}).forEach(function(n){addWifiName(names,seen,n.ssid);});addWifiName(names,seen,connectedWifiSsid());(appState.networks||[]).forEach(function(name){addWifiName(names,seen,name);});return names;}\n"
    "    function visibleWifiNames(names){const connected=connectedWifiSsid();if(!connected||appState.wifiListExpanded)return names;return names.filter(function(name){return name===connected;});}\n"
    "    function toggleWifiListExpanded(){appState.wifiListExpanded=!appState.wifiListExpanded;renderWifiList();}\n"
    "    function appendWifiToggleRow(list,totalCount,visibleCount){const hiddenCount=Math.max(0,totalCount-visibleCount);if(!connectedWifiSsid()||totalCount<=1)return;const row=document.createElement('div');row.className='wifi-toggle-row';const btn=document.createElement('button');btn.type='button';btn.className='button ghost';btn.textContent=appState.wifiListExpanded?'Hide other Wi-Fi':'Show other Wi-Fi ('+String(hiddenCount)+')';btn.onclick=toggleWifiListExpanded;row.appendChild(btn);list.appendChild(row);}\n"
    "    function renderWifiList(){const list=byId('wifiList');list.innerHTML='';const names=displayWifiNames();const visibleNames=visibleWifiNames(names);if(!visibleNames.length){const empty=document.createElement('div');empty.className='wifi-row';const left=document.createElement('div');const title=document.createElement('div');title.className='wifi-main';title.textContent='No networks scanned';const meta=document.createElement('div');meta.className='wifi-meta';meta.textContent='Click \"Rescan\" to try again';left.appendChild(title);left.appendChild(meta);empty.appendChild(left);list.appendChild(empty);return;}const saved=savedWifiNetworks();let maxPriority=0;saved.forEach(function(n){maxPriority=Math.max(maxPriority,Number(n.priority||0));});visibleNames.forEach(function(name){const savedNet=savedWifiBySsid(name);const item=document.createElement('div');let cls='wifi-row';let meta=[];let state='';if(appState.wifiStatus&&appState.wifiStatus.connected&&appState.wifiStatus.ssid===name){cls+=' current';meta.push(appState.wifiStatus.ip_address?('Connected · '+appState.wifiStatus.ip_address):'Connected');state='✓';}if(savedNet){cls+=' saved';meta.push(Number(savedNet.priority||0)===maxPriority?'Saved · highest priority':'Saved · priority '+String(savedNet.priority||0));}item.className=cls;const left=document.createElement('button');left.type='button';left.className='wifi-connect';left.onclick=function(){if(savedNet){connectSavedWifi(name);}else{openWifiModal(name);}};const title=document.createElement('div');title.className='wifi-main';title.textContent=name;left.appendChild(title);if(meta.length){const metaEl=document.createElement('div');metaEl.className='wifi-meta';metaEl.textContent=meta.join(' · ');left.appendChild(metaEl);}const right=document.createElement('div');right.className='wifi-state';right.textContent=state;if(savedNet){const forget=document.createElement('button');forget.type='button';forget.className='button ghost';forget.textContent='Forget';forget.onclick=function(event){event.stopPropagation();forgetWifi(name);};right.appendChild(forget);}item.appendChild(left);item.appendChild(right);list.appendChild(item);});appendWifiToggleRow(list,names.length,visibleNames.length);}\n"
    "    function applyPayload(payload,requestLocaleRevision){appState.config=payload.config||{};const configuredLocale=appState.config.agent&&appState.config.agent.locale?appState.config.agent.locale:'zh-CN';if(requestLocaleRevision===localeRevision&&!localeSavePending){applyLocale(configuredLocale,true);}else{appState.config.agent=appState.config.agent||{};appState.config.agent.locale=activeLocale;}appState.wifi=payload.wifi||{};appState.wifiStatus=payload.wifi_status||{};appState.systemEnv=payload.system_env||'';byId('system_env_content').value=appState.systemEnv;renderAgentStatus(payload.agent_status||{});fillConfigForm(appState.config);lockAllSections();renderFirmwareInfo(payload.firmware||{});}\n"
    "    async function loadAuthoritativeLocale(){const payload=await request('/api/config',{method:'GET'});const config=payload.config||{};const locale=config.agent&&config.agent.locale?config.agent.locale:'zh-CN';applyLocale(locale,true);if(appState.config){appState.config.agent=appState.config.agent||{};appState.config.agent.locale=persistedLocale;}return locale;}\n"
    "    async function loadConfig(){const requestLocaleRevision=localeRevision;const payload=await request('/api/config',{method:'GET'});applyPayload(payload,requestLocaleRevision);if(payload.config_error||payload.wifi_error){setDetails([payload.config_error||'',payload.wifi_error||''].filter(Boolean).join('\\n'));}return payload;}\n"
    "    async function scanWifi(showBanner){byId('scanBtn').disabled=true;try{const payload=await request('/api/wifi/scan',{method:'POST'});appState.networks=payload.networks||[];renderWifiList();if(showBanner!==false){setBanner('Wi-Fi list refreshed.',false);setDetails('');}}catch(err){setBanner('Failed to scan Wi-Fi.',true);setDetails(err.message);}finally{byId('scanBtn').disabled=false;}}\n"
    "    async function reloadAll(){byId('reloadBtn').disabled=true;try{await loadConfig();await scanWifi(false);setBanner('Refreshed configuration and Wi-Fi list.',false);}catch(err){setBanner('Refresh failed.',true);setDetails(err.message);}finally{byId('reloadBtn').disabled=false;}}\n"
    "    function openWifiModal(ssid,focusPassword){const saved=savedWifiBySsid(ssid);appState.selectedSsid=ssid;byId('wifiModalText').textContent='Connect to \"'+ssid+'\"';byId('wifiPasswordInput').value=saved&&saved.psk?saved.psk:'';byId('wifiModal').classList.add('show');if(focusPassword!==false){byId('wifiPasswordInput').focus();}}\n"
    "    function closeWifiModal(){byId('wifiModal').classList.remove('show');appState.selectedSsid='';}\n"
    "    function connectSavedWifi(ssid){const saved=savedWifiBySsid(ssid);openWifiModal(ssid,false);if(!saved)return;byId('wifiModalText').textContent='Connecting to \"'+ssid+'\"...';const btn=byId('connectWifiBtn');if(btn){btn.disabled=true;btn.textContent='Connecting';}setTimeout(function(){connectWifi(ssid,saved.psk||'');},0);}\n"
    "    async function connectWifi(ssid,psk){const btn=byId('connectWifiBtn');if(btn){btn.disabled=true;btn.textContent='Connecting';}byId('wifiModalText').textContent='Connecting to \"'+ssid+'\"...';try{const payload=await request('/api/wifi/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ssid:ssid,psk:psk})});appState.wifi=payload.wifi||{ssid:ssid,psk:psk};appState.wifiStatus=payload.wifi_status||{};const connected=!!payload.ok&&connectedWifiSsid()===ssid;if(connected){appState.wifiListExpanded=false;}renderWifiList();if(connected){closeWifiModal();setBanner('Connected to \"'+ssid+'\".',false);setDetails('');}else{byId('wifiModalText').textContent='Failed to connect to \"'+ssid+'\", please check password and try again.';setBanner('Failed to connect to Wi-Fi.',true);setDetails(payload.wifi_apply&&payload.wifi_apply.output?payload.wifi_apply.output:'Connection not confirmed to target network.');}}catch(err){byId('wifiModalText').textContent='Failed to connect to \"'+ssid+'\", please check password and try again.';setBanner('Failed to connect to Wi-Fi.',true);setDetails(err.message);}finally{if(btn){btn.disabled=false;btn.textContent='Connect';}}}\n"
    "    function connectSelectedWifi(){return connectWifi(appState.selectedSsid,byId('wifiPasswordInput').value);}\n"
    "    async function forgetWifi(ssid){if(!window.confirm(localizedText('Forget \"'+ssid+'\"?')))return;try{const payload=await request('/api/wifi/forget',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ssid:ssid})});appState.wifi=payload.wifi||{};appState.wifiStatus=payload.wifi_status||{};renderWifiList();if(payload.ok!==false){setBanner('Forgot \"'+ssid+'\".',false);setDetails('');}else{setBanner('Forgot \"'+ssid+'\", but runtime apply failed.',true);setDetails(payload.wifi_apply&&payload.wifi_apply.output?payload.wifi_apply.output:'Network removed from saved list, but runtime config update failed.');}}catch(err){setBanner('Failed to forget Wi-Fi.',true);setDetails(err.message);}}\n"
    "    async function rebootDevice(){setBanner('Rebooting...',false);setDetails('Sent reboot request, device will reboot.');try{await request('/api/reboot',{method:'POST'});setDetails('reboot command sent. Please wait for USB disconnect and re-enumeration before refreshing page.');}catch(err){setBanner('Reboot failed.',true);setDetails(err.message);}}\n"
    "    async function saveSection(section){if(!appState.config){return;}if(sectionModeLocked(section)){setBanner('['+section+'] can only be saved when agent.input_mode = stt.',false);setDetails('First change input_mode to stt in [agent] and save.');return;}byId('save-'+section).disabled=true;try{appState.config[section]=readSection(section);const payload=await request('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({config:appState.config,apply_wifi:false})});if(payload.config){appState.config=payload.config;}fillConfigForm(appState.config);delete sectionSnapshots[section];setSectionLocked(section,true);byId('section-'+section).classList.remove('editing');if(payload.reboot_required){setBanner('USB HID configuration saved. Reboot the board for it to take effect.',false);setDetails('Will not hot-restart or re-enumerate USB HID to avoid an inconsistent host USB session.');if(window.confirm(localizedText('USB HID settings saved, requires reboot to take effect. Reboot now?'))){await rebootDevice();}else{setDetails('Cancelled immediate reboot. Please reboot manually later, then verify USB HID after reboot.');}}else{setBanner('['+section+'] saved.',false);setDetails('');setTimeout(function(){refreshAgentStatus(false);},1200);}}catch(err){setBanner('Save ['+section+'] failed.',true);setDetails(err.message);setSectionLocked(section,false);}finally{byId('save-'+section).disabled=false;}}\n"
    "    async function saveSystemEnv(){byId('save-system_env').disabled=true;try{const payload=await request('/api/system/env',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({system_env:byId('system_env_content').value})});appState.systemEnv=payload.system_env||byId('system_env_content').value;byId('system_env_content').value=appState.systemEnv;setSystemEnvLocked(true);byId('section-system_env').classList.remove('editing');setBanner('env saved.',false);setDetails('');setTimeout(function(){refreshAgentStatus(false);},1200);}catch(err){setBanner('Failed to save env.',true);setDetails(err.message);setSystemEnvLocked(false);}finally{byId('save-system_env').disabled=false;}}\n"
    "    function closeTestToast(){byId('testToast').classList.remove('show','pass','fail');}\n"
    "    async function testSection(section){if(sectionModeLocked(section)){setBanner('['+section+'] can only be tested when agent.input_mode = stt.',false);setDetails('First change input_mode to stt in [agent] and save.');return;}var toast=byId('testToast');toast.className='test-toast show';byId('testToastTitle').textContent='Testing ['+section+'] and';byId('testToastBody').textContent='';try{const values=readSection(section);const payload=await request('/api/config/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({section:section,values:values})});const results=payload.results||[];let detail='';results.forEach(function(r){detail+=(r.passed?'\\u2705':'\\u274C')+' '+r.check+': '+r.detail+'\\n';});toast.className='test-toast show '+(payload.ok?'pass':'fail');byId('testToastTitle').textContent=payload.ok?'['+section+'] test passed':'['+section+'] test not passed';byId('testToastBody').textContent=detail;}catch(err){toast.className='test-toast show fail';byId('testToastTitle').textContent='Test ['+section+'] failed';byId('testToastBody').textContent=err.message;}}\n"
    "    window.addEventListener('click',function(event){if(event.target===byId('wifiModal')){closeWifiModal();}});\n"
    "    document.addEventListener('selectionchange',applyPendingAgentLogSnapshotIfIdle);\n"
    "    const systemEnvEditor=byId('system_env_content');if(systemEnvEditor){systemEnvEditor.addEventListener('keydown',handleSystemEnvEditorKeydown);}\n"
    "    if(byId('agentLogText')){byId('agentLogText').addEventListener('scroll',syncAgentLogAutoScroll);}setAgentLogAutoScroll(true);\n"
    "    async function loadConfigMeta(){const meta=await request('/api/config/meta',{method:'GET'});buildConfigMeta(meta);}\n"
    "    function disableAgentConfigEditing(){document.querySelectorAll('.section-card').forEach(function(card){if(card.id==='section-system_env')return;card.classList.remove('editing');card.querySelectorAll('button,input,select,textarea').forEach(function(el){el.disabled=true;});});}\n"
    "    function initialReadyMessage(metaOk){if(!metaOk)return 'Failed to read configuration metadata: agent.toml editing disabled, Wi-Fi and logs still work normally.';if(connectedWifiSsid())return 'Wi-Fi connected.';return 'Please select Wi-Fi, or edit agent.toml by section.';}\n"
    "    (async function init(){configureTerminalLink();let metaOk=true;setBanner('Reading configuration metadata...',false);try{await loadConfigMeta();}catch(err){metaOk=false;setDetails(err.message);}if(metaOk){hydrateSelectOptions();bindFieldVisibility();}lockAllSections();setBanner('Reading configuration...',false);try{await loadConfig();await scanWifi(false);await refreshAgentLog(false);setBanner(initialReadyMessage(metaOk),!metaOk);}catch(err){setBanner('Page initialization failed.',true);setDetails(err.message);}if(!metaOk){disableAgentConfigEditing();}refreshStorage(false);setInterval(function(){refreshAgentStatus(false);},5000);setInterval(function(){refreshAgentLog(false);},2000);setInterval(function(){refreshOtaLog(false);},2000);setInterval(function(){refreshStorage(false);},3000);})();\n"
    "  </script>\n"
    "</body>\n"
    "</html>\n";
